// camera.ts 파일 내에 이 함수도 추가해야 합니다
function rayIntersectsSphere(ray: Ray, center: Vec3, radius: number) {
    // 레이 원점에서 구 중심까지의 벡터
    const oc = new Vec3();
    oc.sub2(ray.origin, center);

    // 레이-구 교차 방정식 계수
    const a = ray.direction.dot(ray.direction); // 항상 1 (정규화된 방향)
    const b = 2.0 * oc.dot(ray.direction);
    const c = oc.dot(oc) - radius * radius;

    // 판별식 계산
    const discriminant = b * b - 4 * a * c;

    if (discriminant < 0) {
        // 교차점 없음
        return { intersects: false, distance: Infinity };
    }

    // 가장 가까운 교차점까지의 거리 계산
    const distance = (-b - Math.sqrt(discriminant)) / (2.0 * a);

    // 양수 거리만 유효 (레이 앞쪽에 있는 교차점)
    if (distance < 0) {
        return { intersects: false, distance: Infinity };
    }

    return { intersects: true, distance: distance };
}
export { Camera };
